  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C33"],
      "claim": "Nifedipine had an absolute bioavailability of 0.43 ± 0.14 after a 30 mg oral tablet dose (C33), supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "The compound in C24 had 34% oral bioavailability in healthy volunteers in the fasted state after a 100 mg immediate-release dose versus intravenous dosing, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "Pentazocine had an absolute oral bioavailability of 18.5% in healthy subjects after 2 x 50 mg tablets versus IV (C34), below the 20% threshold.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted high because most transferred human bioavailability records are above 20%, including nifedipine 43%, the C24 compound 34%, rigosertib 35%, soraprazan 50%, and methocarbamol 90%; only pentazocine is clearly below 20%, while isradipine is mixed and one provenance conflict was discounted.",
  "evidence_gaps": [
    "Molecule 2 has conflicting healthy-volunteer bioavailability values (16-19% vs 28%), making its direction mixed.",
    "Molecule 6 groups records for different compounds (ORH-2014 and TSU-68), so those cards were discounted.",
    "Molecule 4 provides only qualitative 'good' bioavailability without a numeric F value."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

